namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Instructor { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }

    public string FullCode => $"{DepartmentCode} {CourseNumber}";
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She received her PhD from MIT.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming).", Credits = 4, Schedule = "TTh 10:30–11:50 AM", Instructor = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm design and competitive programming. He has published over 40 papers in top conferences.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "310", Title = "Database Systems", Description = "Design and implementation of relational database systems. Covers SQL, normalization, indexing, and transaction processing.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", Instructor = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez worked at Oracle for 10 years before joining academia. Her research focuses on distributed databases." },
            new() { Id = 4, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "450", Title = "Machine Learning", Description = "Introduction to machine learning algorithms including supervised learning, unsupervised learning, and neural networks.", Credits = 3, Schedule = "TTh 2:00–3:20 PM", Instructor = "Dr. Wei Zhang", InstructorBio = "Dr. Zhang leads the university's AI research lab and has contributed to several open-source ML frameworks.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", Instructor = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an award-winning educator with a passion for making calculus accessible to all students." },
            new() { Id = 6, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "TTh 9:00–10:20 AM", Instructor = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov's research spans abstract algebra and its applications in cryptography.", IsFeatured = true },
            new() { Id = 7, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", Instructor = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an award-winning educator with a passion for making calculus accessible to all students." },
            new() { Id = 8, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab F 2:00–4:00 PM", Instructor = "Dr. Michael Adams", InstructorBio = "Dr. Adams is an experimental physicist whose work on quantum optics has been featured in Nature." },
            new() { Id = 9, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "TTh 1:00–2:20 PM + Lab W 3:00–5:00 PM", Instructor = "Dr. Lisa Nguyen", InstructorBio = "Dr. Nguyen researches high-energy particle physics and has worked at CERN." },
            new() { Id = 10, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "101", Title = "Composition & Rhetoric", Description = "Develop effective writing skills through essay composition, argumentation, and rhetorical analysis.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", Instructor = "Prof. Amanda Foster", InstructorBio = "Prof. Foster is a published author and writing coach with expertise in academic and creative writing." },
            new() { Id = 11, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Explores major authors and literary movements.", Credits = 3, Schedule = "TTh 11:00 AM–12:20 PM", Instructor = "Dr. David Kim", InstructorBio = "Dr. Kim specializes in 20th-century American fiction and has authored three books on the subject.", IsFeatured = true },
            new() { Id = 12, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the Renaissance, covering major political, social, and cultural developments.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", Instructor = "Dr. Patricia Okafor", InstructorBio = "Dr. Okafor is a historian of ancient civilizations with archaeological fieldwork experience in West Africa and the Mediterranean." },
            new() { Id = 13, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "205", Title = "Modern European History", Description = "Europe from the Enlightenment to the present day, including revolutions, world wars, and the formation of the EU.", Credits = 3, Schedule = "TTh 3:30–4:50 PM", Instructor = "Dr. Hans Mueller", InstructorBio = "Dr. Mueller is a specialist in 20th-century European history with a focus on post-war reconstruction." },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.FullCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollmentRequests.Add(request);
    }
}

